import subprocess
from store import Store, ReceiptUnavailable

def load_save(revision):
    source = subprocess.check_output([\"git\", \"show\", revision], text=True)
    namespace = {}
    exec(compile(source, revision, \"exec\"), namespace)
    return namespace[\"save\"]

def fresh_id(save):
    store = Store()
    save(store, \"w\", \"op-1\", {\"color\": \"blue\"})
    result = save(store, \"w\", \"op-2\", {\"color\": \"red\"})
    correct = store.preferences[\"w\"] == {\"color\": \"red\"} and \"op-2\" in store.recovery
    return correct, {\"result\": result, \"preferences\": store.preferences, \"recovery_ids\": list(store.recovery)}

def edited_retry(save):
    store = Store()
    store.fail_receipt_once = True
    try:
        save(store, \"w\", \"op-1\", {\"color\": \"blue\"})
    except ReceiptUnavailable:
        pass
    result = save(store, \"w\", \"op-1\", {\"color\": \"red\"})
    correct = store.preferences[\"w\"] == {\"color\": \"red\"} and store.recovery[\"op-1\"][\"values\"] == {\"color\": \"red\"}
    return correct, {\"result\": result, \"preferences\": store.preferences, \"recovery\": store.recovery}

def completed_replay(save):
    store = Store()
    first = save(store, \"w\", \"op-1\", {\"color\": \"blue\"})
    store.fail_receipt_once = True
    try:
        repeated = save(store, \"w\", \"op-1\", {\"color\": \"blue\"})
        return repeated == first, {\"result\": repeated}
    except ReceiptUnavailable as exc:
        return False, {\"exception\": type(exc).__name__, \"status\": store.recovery[\"op-1\"][\"status\"]}

for revision in (\"HEAD:service.py\", \":service.py\"):
    save = load_save(revision)
    print(revision)
    for check in (fresh_id, edited_retry, completed_replay):
        correct, details = check(save)
        print(check.__name__, \"PASS\" if correct else \"FAIL\", details)
PY"

